#include <iostream>
#include <cstring>
using namespace std;

typedef long long i64;

i64 memo[50][50];

i64 f(int h, int n)
{
    if (h < 0 || h > n)
        return 0;
    if (h == 0)
        return n == 0 ? 1 : 0;

    i64& ret = memo[h][n];
    if (ret != -1)
        return ret;

    ret = 0;
    for (int i = 1; i <= n; ++i)
    {
        int ln = i - 1;
        int rn = n - i;

        for (int hl = 0; hl < h - 1; ++hl)
            ret += f(hl, ln) * f(h - 1, rn)
                 + f(h - 1, ln) * f(hl, rn);

        ret += f(h - 1, ln) * f(h - 1, rn);
    }

    return ret;
}

int main()
{
    int n, h;
    cin >> n >> h;

    memset(memo, -1, sizeof(memo));

    i64 ans = 0;
    for (int hx = h; hx <= n; ++hx)
        ans += f(hx, n);

    cout << ans << '\n';
    return 0;
}

